"use strict";(globalThis.webpackChunkgrc||=[]).push([[84360],{38891(e){e.exports=JSON.parse('{"citeKey":"devarajan2019intelligent","slug":"devarajan-2019-intelligent--e9fd","title":"An Intelligent, Adaptive, and Flexible Data Compression Framework","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"IEEE/ACM International Symposium in Cluster, Cloud, and Grid Computing (CCGrid\'19), Larnaca, Cyprus2019. pp. 82-91.","type":"Conference","entryType":"inproceedings","date":"May, 2019","year":2019,"era":"iit","month":5,"doi":"10.1109/ccgrid.2019.00019","abstract":"The data explosion phenomenon in modern appli- cations causes tremendous stress on storage systems. Developers use data compression, a size-reduction technique, to address this issue. However, each compression library exhibits different strengths and weaknesses when considering the input data type and format. We present Ares, an intelligent, adaptive, and flexible compression framework which can dynamically choose a compression library for a given input data based on the type of the workload and provides an appropriate infrastructure to users to fine-tune the chosen library. Ares is a modular framework which unifies several compression libraries while allowing the addition of more compression libraries by the user. Ares is a unified compression engine that abstracts the complexity of using different compression libraries for each workload. Evaluation results show that under real-world applications, from both scientific and Cloud domains, Ares performed 2-6x faster than competitive solutions with a low cost of additional data analysis (i.e., overheads around 10%) and up to 10x faster against a baseline of no compression at all.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2019/devarajan-2019-intelligent--e9fd.pdf","slides":"https://grc.iit.edu/papers/2019/devarajan-2019-intelligent--e9fd-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes","iris","direcmr","ides","integrated-data-mgmt"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["hermes","iris","ides","direcmr","integrated-data-mgmt"],"memberAuthors":["devarajan-hariharan","kougkas-anthony","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"CSR-1814872","projectId":"iris"},{"agency":"NSF","award":"CCF-1744317","projectId":"direcmr"},{"agency":"NSF","award":"CNS-1730488","projectId":"ides"},{"agency":"NSF","award":"CNS-1526887","projectId":"integrated-data-mgmt"}]}')}}]);